mapper.select:
SELECT COUNT(*)
  FROM genomic_samples gs
 WHERE 1=1
 AND gs.tenant_id = #{tenantId}
 AND gs.status = #{status}

   AND (gs.sample_no ILIKE '%' || #{search} || '%')

SELECT gs.sample_id AS sampleId, gs.sample_no AS sampleNo, gs.patient_id AS patientId, '' AS patientName, gs.sample_type AS sampleType, gp.name AS panelName, gs.status, gs.received_date AS receivedDate, gs.completed_date AS completedDate, gs.created_at AS createdAt FROM genomic_samples gs LEFT JOIN gene_panels gp ON gp.panel_id = gs.panel_id WHERE 1=1 AND gs.tenant_id = #{tenantId} AND gs.status = #{status}
AND (gs.sample_no ILIKE '%' || #{search} || '%')
ORDER BY gs.sample_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE genomic_samples
   SET status = #{status},
       completed_date = CASE WHEN #{status} IN ('COMPLETED', 'REPORTED') THEN CURRENT_DATE ELSE completed_date END,
       updated_at = NOW()
 WHERE sample_id = #{sampleId}
 AND tenant_id = #{tenantId}
